import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { ledgerStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'books-store',
  description:
    "Read and update the books: the ledger (ledger.json), the month-close checklist (close.json) and the receipts inbox (inbox/). action:'status' for last month's P&L, the close checklist and what is waiting; 'record' to book money in or out (the same receipt, or the same payee, date and amount, updates the entry instead of adding it twice); 'categorize' to give an entry its category; 'tick' to check off a close step; 'close' to close a finished month once every step is done; 'reopen' to reopen a closed month; 'list' for the entries.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'record', 'categorize', 'tick', 'close', 'reopen', or 'list'.",
      required: true,
    },
    id: { type: 'string', description: "Ledger entry id, e.g. 'ledger-7'." },
    payee: {
      type: 'string',
      description: "Who was paid, or who paid, e.g. 'Hillside Hardware'. Also finds an entry when no id is given.",
    },
    amount: { type: 'number', description: 'Amount in ordinary units, e.g. 284.17. Always positive.' },
    kind: {
      type: 'string',
      description: "expense or income. Defaults from the category; a supplier's refund is income on its expense category.",
    },
    category: { type: 'string', description: 'materials, subcontractors, payroll, vehicle, tools, insurance, rent, utilities, software, marketing, office, professional-fees, bank-fees, licenses, meals, other, sales, other-income, owner-draw, uncategorized.' },
    date: { type: 'string', description: 'The day the money moved, YYYY-MM-DD (default today).' },
    file: { type: 'string', description: "The receipt's path in the inbox, e.g. 'inbox/hillside-1029.jpg'." },
    note: { type: 'string', description: 'What it was for, with any reference number exactly as written.' },
    month: { type: 'string', description: 'A month, YYYY-MM (default: the month being closed).' },
    step: { type: 'string', description: 'A close step: receipts, categories, bank, card, payroll, income, review.' },
    done: { type: 'boolean', description: 'For tick: false unticks the step.' },
  },
  outputs: {
    waiting: { type: 'number', description: 'Receipts in the inbox not booked yet.' },
    uncategorized: { type: 'number', description: 'Entries that still need a category.' },
    closeMonth: { type: 'string', description: 'The month being closed, YYYY-MM.' },
    stepsLeft: { type: 'number', description: 'Close steps still to do for that month.' },
    net: { type: 'number', description: "That month's net profit, in ordinary units like amount (negative for a loss)." },
    summary: { type: 'string', description: 'What changed, then the books picture; or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── books-rules-start ──
// Pure derivations shared by the script, the page and the sample conversation:
// integer-cent money, the P&L by category group, the receipts still waiting in
// the inbox, and the month-close checklist. Kept self-contained between these
// sentinels so unit tests execute the shipped bytes.
var CATEGORY_GROUP = {
  materials: 'cost',
  subcontractors: 'cost',
  payroll: 'expense',
  vehicle: 'expense',
  tools: 'expense',
  insurance: 'expense',
  rent: 'expense',
  utilities: 'expense',
  software: 'expense',
  marketing: 'expense',
  office: 'expense',
  'professional-fees': 'expense',
  'bank-fees': 'expense',
  licenses: 'expense',
  meals: 'expense',
  other: 'expense',
  sales: 'income',
  'other-income': 'income',
  'owner-draw': 'equity',
  uncategorized: 'unsorted',
};
var CATEGORIES = Object.keys(CATEGORY_GROUP);
var CATEGORY_WORDS = {
  income: 'sales', revenue: 'sales', sale: 'sales', job: 'sales', jobs: 'sales', interest: 'other-income', refund: 'other-income',
  material: 'materials', supplies: 'materials', supply: 'materials', parts: 'materials', stock: 'materials',
  subcontractor: 'subcontractors', contractor: 'subcontractors', contractors: 'subcontractors',
  wages: 'payroll', salary: 'payroll', salaries: 'payroll',
  fuel: 'vehicle', gas: 'vehicle', van: 'vehicle', truck: 'vehicle', mileage: 'vehicle',
  tool: 'tools', equipment: 'tools',
  advertising: 'marketing', ads: 'marketing',
  phone: 'utilities', internet: 'utilities', electric: 'utilities',
  legal: 'professional-fees', accounting: 'professional-fees', accountant: 'professional-fees',
  fees: 'bank-fees', 'bank-fee': 'bank-fees', license: 'licenses', permit: 'licenses', permits: 'licenses',
  meal: 'meals', food: 'meals', draw: 'owner-draw', 'owner-draws': 'owner-draw',
  unknown: 'uncategorized', 'not-sure': 'uncategorized',
};
var GROUP_ORDER = ['income', 'cost', 'expense', 'equity'];
var STEPS = [
  { id: 'receipts', label: 'Book every receipt in the inbox', words: ['receipt', 'inbox'] },
  { id: 'categories', label: 'Give every entry a category', words: ['categor'] },
  { id: 'bank', label: 'Match the bank statement', words: ['bank', 'checking'] },
  { id: 'card', label: 'Match the card statement', words: ['card', 'credit'] },
  { id: 'payroll', label: 'Record payroll and subcontractor payments', words: ['payroll', 'wage', 'subcontract'] },
  { id: 'income', label: 'Record every customer payment', words: ['customer', 'payment', 'invoice', 'income', 'deposit'] },
  { id: 'review', label: 'Review the P&L with the owner', words: ['review', 'p&l', 'owner', 'profit'] },
];
var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function normalizeDate(text) {
  var raw = String(text || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  var parsed = Date.parse(raw);
  return isFinite(parsed) ? localDay(parsed) : null;
}
function prevMonth(month) {
  var y = Number(month.slice(0, 4));
  var m = Number(month.slice(5, 7)) - 1;
  if (m < 1) {
    m = 12;
    y -= 1;
  }
  return y + '-' + pad(m);
}
function monthName(month) {
  return MONTHS[Number(String(month).slice(5, 7)) - 1] + ' ' + String(month).slice(0, 4);
}
// 'YYYY-MM', a date, 'last month', or a month name; a bare name means its latest past or current occurrence.
function normalizeMonth(text, nowMs) {
  var raw = String(text || '').trim().toLowerCase();
  var current = localDay(nowMs).slice(0, 7);
  if (/^\d{4}-\d{2}$/.test(raw)) return raw;
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw.slice(0, 7);
  if (/last|previous/.test(raw)) return prevMonth(current);
  if (/this|current/.test(raw)) return current;
  for (var i = 0; i < 12; i++) {
    if (raw.indexOf(MONTHS[i].toLowerCase().slice(0, 3)) === 0) {
      var year = raw.match(/\d{4}/);
      var candidate = (year ? year[0] : current.slice(0, 4)) + '-' + pad(i + 1);
      if (!year && candidate > current) candidate = Number(current.slice(0, 4)) - 1 + '-' + pad(i + 1);
      return candidate;
    }
  }
  return null;
}
// Integer cents from 284.17, '284.17' or '$1,912.40', with no float arithmetic; null unless positive.
function toCents(value) {
  var text = typeof value === 'number' ? (isFinite(value) ? String(value) : '') : String(value == null ? '' : value);
  var m = /^(\d+)(?:\.(\d*))?$/.exec(text.replace(/[$,\s]/g, ''));
  if (!m) return null;
  var frac = (m[2] || '') + '000';
  var cents = Number(m[1]) * 100 + Number(frac.slice(0, 2)) + (Number(frac.charAt(2)) >= 5 ? 1 : 0);
  return cents > 0 ? cents : null;
}
function money(cents) {
  var abs = Math.abs(Math.round(cents));
  var whole = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (cents < 0 ? '-' : '') + whole + '.' + pad(abs % 100);
}
function normalizeCategory(text) {
  var key = String(text || '').trim().toLowerCase().replace(/&/g, 'and').replace(/[\s_]+/g, '-');
  if (Object.prototype.hasOwnProperty.call(CATEGORY_GROUP, key)) return key;
  if (Object.prototype.hasOwnProperty.call(CATEGORY_WORDS, key)) return CATEGORY_WORDS[key];
  var words = key.split('-');
  for (var i = 0; i < words.length; i++) {
    if (Object.prototype.hasOwnProperty.call(CATEGORY_GROUP, words[i])) return words[i];
    if (Object.prototype.hasOwnProperty.call(CATEGORY_WORDS, words[i])) return CATEGORY_WORDS[words[i]];
  }
  return null;
}
function normalizeStep(text) {
  var raw = String(text || '').trim().toLowerCase();
  for (var i = 0; i < STEPS.length; i++) if (STEPS[i].id === raw) return STEPS[i].id;
  for (var j = 0; j < STEPS.length; j++) {
    for (var k = 0; k < STEPS[j].words.length; k++) if (raw.indexOf(STEPS[j].words[k]) >= 0) return STEPS[j].id;
  }
  return null;
}
function stepLabel(id) {
  for (var i = 0; i < STEPS.length; i++) if (STEPS[i].id === id) return STEPS[i].label;
  return id;
}
function entryDate(entry) {
  return String((entry.data && entry.data.date) || entry.at || '').slice(0, 10);
}
function monthOf(entry) {
  return entryDate(entry).slice(0, 7);
}
function payeeOf(entry) {
  return String((entry.data && entry.data.payee) || entry.note || '');
}
function groupOf(entry) {
  var group = CATEGORY_GROUP[entry.category] || 'expense';
  return group === 'unsorted' ? (entry.kind === 'in' ? 'income' : 'expense') : group;
}
function entryLine(entry) {
  return (
    entry.id + ' ' + entryDate(entry) + ' ' + payeeOf(entry) + ' ' + money(entry.amountCents) +
    (entry.kind === 'in' ? ' in, ' : ' out, ') + entry.category +
    (entry.data && entry.data.file ? ' (receipt ' + entry.data.file + ')' : '')
  );
}
// The month's P&L: income less cost of jobs is gross profit; less expenses is net profit. Owner draws stay off it.
function pnl(entries, month) {
  var rows = {};
  var totals = { income: 0, cost: 0, expense: 0, equity: 0 };
  var count = 0;
  entries.forEach(function (e) {
    if (monthOf(e) !== month) return;
    count += 1;
    var group = groupOf(e);
    var cents = e.kind === (group === 'income' ? 'in' : 'out') ? e.amountCents : -e.amountCents;
    totals[group] += cents;
    var key = group + ':' + e.category;
    if (!rows[key]) rows[key] = { group: group, category: e.category, cents: 0 };
    rows[key].cents += cents;
  });
  var lines = Object.keys(rows)
    .map(function (k) { return rows[k]; })
    .sort(function (a, b) { return GROUP_ORDER.indexOf(a.group) - GROUP_ORDER.indexOf(b.group) || b.cents - a.cents; });
  var gross = totals.income - totals.cost;
  return {
    month: month, count: count, incomeCents: totals.income, costCents: totals.cost, grossCents: gross,
    expenseCents: totals.expense, netCents: gross - totals.expense, drawCents: totals.equity, lines: lines,
  };
}
function pnlLine(p) {
  if (!p.count) return monthName(p.month) + ': nothing booked.';
  var part = function (group) {
    var rows = p.lines.filter(function (l) { return l.group === group; }).map(function (l) { return l.category + ' ' + money(l.cents); });
    return rows.length ? ' (' + rows.join(', ') + ')' : '';
  };
  return (
    monthName(p.month) + ': income ' + money(p.incomeCents) + part('income') +
    '; cost of jobs ' + money(p.costCents) + part('cost') +
    '; gross profit ' + money(p.grossCents) +
    '; expenses ' + money(p.expenseCents) + part('expense') +
    '; net profit ' + money(p.netCents) + (p.netCents < 0 ? ' (a loss)' : '') +
    (p.drawCents ? '; owner draws ' + money(p.drawCents) + ', not on the P&L' : '') + '.'
  );
}
// Inbox files that no entry names as its receipt yet.
function waitingFiles(names, entries) {
  var booked = {};
  entries.forEach(function (e) {
    if (e.data && e.data.file) booked[String(e.data.file)] = true;
  });
  return names
    .filter(function (n) { return n.charAt(0) !== '.' && !booked['inbox/' + n]; })
    .map(function (n) { return 'inbox/' + n; });
}
function needsCategory(entries, month) {
  return entries.filter(function (e) { return e.category === 'uncategorized' && (!month || monthOf(e) === month); });
}
function closeRecord(closes, month) {
  for (var i = 0; i < closes.length; i++) if (closes[i].fields && closes[i].fields.month === month) return closes[i];
  return null;
}
function isClosed(closes, month) {
  var r = closeRecord(closes, month);
  return !!r && r.status === 'closed';
}
// The month to close: the earliest finished month with entries that is still open, else last month.
function monthToClose(entries, closes, nowMs) {
  var current = localDay(nowMs).slice(0, 7);
  var months = {};
  entries.forEach(function (e) {
    var m = monthOf(e);
    if (m && m < current) months[m] = true;
  });
  closes.forEach(function (r) {
    if (r.fields && r.fields.month && r.fields.month < current) months[r.fields.month] = true;
  });
  var open = Object.keys(months).filter(function (m) { return !isClosed(closes, m); }).sort();
  return open.length ? open[0] : prevMonth(current);
}
function closeView(month, entries, closes, waiting) {
  var rec = closeRecord(closes, month);
  var fields = (rec && rec.fields) || {};
  var done = fields.done || {};
  var notes = fields.notes || {};
  var closed = !!rec && rec.status === 'closed';
  var unsorted = needsCategory(entries, month);
  var steps = STEPS.map(function (s) {
    var ticked = !!done[s.id];
    var auto = s.id === 'receipts' ? waiting.length === 0 : s.id === 'categories' ? unsorted.length === 0 : false;
    var ok = closed || (s.id === 'categories' ? auto : auto || ticked);
    return { id: s.id, label: s.label, done: ok, on: done[s.id] || '', note: notes[s.id] || '', auto: auto && !ticked };
  });
  var left = steps.filter(function (s) { return !s.done; });
  return { month: month, closed: closed, closedOn: fields.closedOn || '', steps: steps, left: left, ready: !closed && left.length === 0, unsorted: unsorted };
}
function closeLine(view) {
  if (view.closed) return monthName(view.month) + ' is closed' + (view.closedOn ? ' (closed ' + view.closedOn + ')' : '') + '.';
  var count = view.steps.length - view.left.length;
  return (
    'Close of ' + monthName(view.month) + ': ' + count + ' of ' + view.steps.length + ' steps done. ' +
    (view.ready
      ? 'Every step is done, so it is ready to close.'
      : 'Still to do: ' + view.left.map(function (s) { return s.label + ' (' + s.id + ')'; }).join('; ') + '.')
  );
}
function picture(entries, closes, inboxNames, nowMs, focusMonth) {
  var current = localDay(nowMs).slice(0, 7);
  var last = prevMonth(current);
  var closing = monthToClose(entries, closes, nowMs);
  var waiting = waitingFiles(inboxNames, entries);
  var unsorted = needsCategory(entries);
  var view = closeView(closing, entries, closes, waiting);
  var parts = [];
  var shown = [];
  function addPnl(month) {
    if (!month || shown.indexOf(month) >= 0) return;
    shown.push(month);
    var label = month === last ? 'P&L for last month, ' : month === current ? 'This month so far, ' : 'P&L for ';
    parts.push(label + pnlLine(pnl(entries, month)));
  }
  addPnl(focusMonth);
  addPnl(last);
  addPnl(closing);
  parts.push(closeLine(view));
  parts.push(
    waiting.length
      ? waiting.length + (waiting.length === 1 ? ' receipt is' : ' receipts are') + ' waiting in the inbox to be booked: ' + waiting.join(', ') + '.'
      : 'No receipts are waiting in the inbox.',
  );
  parts.push(
    unsorted.length
      ? unsorted.length + (unsorted.length === 1 ? ' entry needs' : ' entries need') + ' a category: ' + unsorted.map(entryLine).join(' | ') + '.'
      : 'Every entry has a category.',
  );
  addPnl(current);
  var closedMonths = closes
    .filter(function (r) { return r.status === 'closed' && r.fields && r.fields.month; })
    .map(function (r) { return r.fields.month; })
    .sort();
  if (closedMonths.length) parts.push('Closed months: ' + closedMonths.map(monthName).join(', ') + '.');
  return { closing: closing, view: view, waiting: waiting, unsorted: unsorted, netCents: pnl(entries, closing).netCents, summary: parts.join(' ') };
}
// ── books-rules-end ──

type Entry = {
  id: string;
  at: string;
  amountCents: number;
  kind: 'in' | 'out';
  category: string;
  note?: string;
  data?: Record<string, unknown>;
};

const ledger = ledgerStore(gezel.fs, 'ledger.json');
const closeBook = rosterStore(gezel.fs, 'close.json', { stages: ['open', 'closed'], idPrefix: 'close' });
const now = Date.now();
const today = localDay(now);
const currentMonth = today.slice(0, 7);

async function inboxNames(): Promise<string[]> {
  try {
    return (await gezel.fs.list('inbox')).filter((e) => !e.isDirectory).map((e) => e.name).sort();
  } catch {
    return [];
  }
}

// ledgerStore only appends; a correction rewrites the one entry in place, in the store's own file format.
async function patchEntry(id: string, patch: (entry: Entry) => void): Promise<Entry> {
  const file = JSON.parse(await gezel.fs.read('ledger.json')) as { entries: Entry[] };
  const entry = file.entries.find((e) => e.id === id);
  if (!entry) throw new Error('No ledger entry ' + id + '.');
  patch(entry);
  await gezel.fs.write('ledger.json', JSON.stringify(file, null, 2) + '\n');
  return entry;
}

function resolveEntry(all: Entry[]): Entry {
  if (input.id) {
    const hit = all.find((e) => e.id === input.id);
    if (hit) return hit;
    throw new Error("No entry '" + input.id + "'. Call action:'list' to see the entries.");
  }
  const wanted = (input.payee ?? '').trim().toLowerCase();
  if (wanted) {
    let hits = all.filter((e) => payeeOf(e).toLowerCase() === wanted);
    if (!hits.length) {
      hits = all.filter((e) => {
        const p = payeeOf(e).toLowerCase();
        return !!p && (p.includes(wanted) || wanted.includes(p));
      });
    }
    const cents = toCents(input.amount);
    if (hits.length > 1 && cents) {
      const same = hits.filter((e) => e.amountCents === cents);
      if (same.length) hits = same;
    }
    if (hits.length > 1) {
      const unsorted = hits.filter((e) => e.category === 'uncategorized');
      if (unsorted.length === 1) hits = unsorted;
    }
    if (hits.length === 1) return hits[0]!;
    if (hits.length > 1) {
      throw new Error("More than one entry matches '" + input.payee + "': " + hits.map(entryLine).join(' | ') + '. Pass id.');
    }
  }
  throw new Error("Pass 'id' (e.g. 'ledger-7') or the entry's 'payee'. Call action:'list' to see the entries.");
}

function kindOf(text: string | undefined): 'in' | 'out' | null {
  const k = String(text ?? '').trim().toLowerCase();
  return k === 'income' || k === 'in' ? 'in' : k === 'expense' || k === 'out' ? 'out' : null;
}
function naturalKind(category: string): 'in' | 'out' {
  return CATEGORY_GROUP[category] === 'income' ? 'in' : 'out';
}
function normalizeFile(file: string): string {
  const clean = file.trim().replace(/\\/g, '/').replace(/^\.?\//, '');
  return clean.includes('/') ? clean : 'inbox/' + clean;
}
function pickMonth(all: Entry[], closes: unknown[]): string {
  const month = input.month ? normalizeMonth(input.month, now) : monthToClose(all, closes, now);
  if (!month) throw new Error("month must be YYYY-MM, e.g. '" + prevMonth(currentMonth) + "'.");
  if (month >= currentMonth) throw new Error(monthName(month) + " isn't over yet. Close steps are for a finished month.");
  return month;
}
async function ensureClose(month: string, closes: unknown[]) {
  const found = closeRecord(closes, month);
  if (found) return found;
  return closeBook.add({ id: 'close-' + month, status: 'open', fields: { month, done: {}, notes: {} } });
}
function lockedMessage(month: string): string {
  return monthName(month) + ' is closed. Reopen it first (reopen_month), or date the entry in an open month.';
}

const closeList = await closeBook.list();
let note = '';

if (input.action === 'record') {
  const cents = toCents(input.amount);
  if (cents === null) throw new Error("record needs a positive 'amount' in ordinary units, e.g. 284.17.");
  const payee = (input.payee ?? '').trim();
  if (!payee) throw new Error("record needs 'payee': who was paid, or who paid.");
  const date = input.date ? normalizeDate(input.date) : today;
  if (!date) throw new Error("date must be a date, e.g. '" + today + "'.");
  const category = input.category ? normalizeCategory(input.category) : null;
  if (input.category && !category) {
    throw new Error("Unknown category '" + input.category + "'. Use one of: " + CATEGORIES.join(', ') + '.');
  }
  const explicit = kindOf(input.kind);
  const kind = explicit ?? naturalKind(category ?? 'uncategorized');
  const file = input.file ? normalizeFile(input.file) : undefined;
  if (isClosed(closeList, date.slice(0, 7))) throw new Error(lockedMessage(date.slice(0, 7)));
  const all = (await ledger.list()) as Entry[];
  const same = all.find(
    (e) =>
      (file && e.data?.file === file) ||
      (entryDate(e) === date && e.amountCents === cents && payeeOf(e).toLowerCase() === payee.toLowerCase()),
  );
  if (same) {
    if (isClosed(closeList, monthOf(same))) throw new Error(lockedMessage(monthOf(same)));
    const updated = await patchEntry(same.id, (entry) => {
      entry.amountCents = cents;
      entry.at = date + 'T12:00:00.000Z';
      if (category) entry.category = category;
      if (explicit || category) entry.kind = kind;
      if (input.note) entry.note = input.note.trim();
      // A payee typed differently keeps its booked spelling; a re-read receipt may correct it.
      entry.data = { ...(entry.data ?? {}), date, ...(file && same.data?.file === file ? { payee } : {}), ...(file ? { file } : {}) };
    });
    note = 'Already in the books, so updated it instead of adding it twice: ' + entryLine(updated) + '.';
  } else {
    const added = await ledger.add({
      amountCents: cents,
      kind,
      category: category ?? 'uncategorized',
      at: date + 'T12:00:00.000Z',
      ...(input.note ? { note: input.note.trim() } : {}),
      data: { date, payee, ...(file ? { file } : {}) },
    });
    note = 'Booked ' + entryLine(added) + '.' + (category ? '' : ' It needs a category: ask what it was for.');
  }
} else if (input.action === 'categorize') {
  const category = normalizeCategory(input.category ?? '');
  if (!category || category === 'uncategorized') {
    throw new Error("categorize needs 'category', one of: " + CATEGORIES.filter((c) => c !== 'uncategorized').join(', ') + '.');
  }
  const entry = resolveEntry((await ledger.list()) as Entry[]);
  if (isClosed(closeList, monthOf(entry))) throw new Error(lockedMessage(monthOf(entry)));
  const updated = await patchEntry(entry.id, (e) => {
    const explicit = kindOf(input.kind);
    if (explicit) e.kind = explicit;
    else if (e.category === 'uncategorized') e.kind = naturalKind(category);
    e.category = category;
    if (input.note) e.note = input.note.trim();
  });
  note = payeeOf(updated) + ' (' + updated.id + ', ' + money(updated.amountCents) + ' on ' + entryDate(updated) + ') is now under ' + category + '.';
} else if (input.action === 'tick') {
  const step = normalizeStep(input.step ?? '');
  if (!step) throw new Error("tick needs 'step': " + STEPS.map((s) => s.id).join(', ') + '.');
  const all = (await ledger.list()) as Entry[];
  const month = pickMonth(all, closeList);
  if (step === 'categories') {
    const left = needsCategory(all, month);
    if (left.length) {
      throw new Error(left.length + ' entries in ' + monthName(month) + ' still need a category: ' + left.map(entryLine).join(' | ') + '. Give each one its category; this step checks itself.');
    }
    note = 'Every entry in ' + monthName(month) + ' has a category, so that step checks itself.';
  } else {
    const rec = await ensureClose(month, closeList);
    if (rec.status === 'closed') throw new Error(monthName(month) + ' is already closed. Reopen it to change its checklist.');
    const done: Record<string, string> = { ...((rec.fields.done as Record<string, string>) ?? {}) };
    const notes: Record<string, string> = { ...((rec.fields.notes as Record<string, string>) ?? {}) };
    if (input.done === false) {
      delete done[step];
      delete notes[step];
    } else {
      done[step] = today;
      if (input.note) notes[step] = input.note.trim();
    }
    await closeBook.update(rec.id, { fields: { done, notes }, note: stepLabel(step) + (input.done === false ? ': unticked' : ': done') });
    note = stepLabel(step) + (input.done === false ? ' is unticked' : ' is done') + ' for ' + monthName(month) + '.';
  }
} else if (input.action === 'close') {
  const all = (await ledger.list()) as Entry[];
  const month = pickMonth(all, closeList);
  const existing = closeRecord(closeList, month);
  if (existing && existing.status === 'closed') {
    note = monthName(month) + ' was already closed.';
  } else {
    const view = closeView(month, all, closeList, waitingFiles(await inboxNames(), all));
    if (!view.ready) {
      throw new Error(monthName(month) + ' is not ready to close. Still to do: ' + view.left.map((s) => s.label + ' (' + s.id + ')').join('; ') + '.');
    }
    const rec = existing ?? (await ensureClose(month, closeList));
    const result = pnl(all, month);
    await closeBook.update(rec.id, { fields: { closedOn: today, netCents: result.netCents } });
    await closeBook.transition(rec.id, 'closed', { note: 'Closed with net profit ' + money(result.netCents) });
    note = monthName(month) + ' is closed with net profit ' + money(result.netCents) + '. Its entries are locked until it is reopened.';
  }
} else if (input.action === 'reopen') {
  const closed = closeList.filter((r) => r.status === 'closed').map((r) => String(r.fields.month)).sort();
  const month = input.month ? normalizeMonth(input.month, now) : closed[closed.length - 1];
  if (!month) throw new Error('No month is closed.');
  const rec = closeRecord(closeList, month);
  if (!rec || rec.status !== 'closed') throw new Error(monthName(month) + ' is not closed.');
  await closeBook.transition(rec.id, 'open', { note: input.note ?? 'Reopened' });
  note = monthName(month) + ' is open again. Close it once the change is booked.';
} else if (input.action !== 'status' && input.action !== 'list') {
  throw new Error("Unknown action '" + input.action + "'. Use status, record, categorize, tick, close, reopen, or list.");
}

const entries = (await ledger.list()) as Entry[];
const closes = await closeBook.list();
const focus = input.month ? normalizeMonth(input.month, now) : null;
const view = picture(entries, closes, await inboxNames(), now, input.action === 'status' ? focus : null);
const rows = entries.filter((e) => !focus || monthOf(e) === focus);
const listing =
  input.action === 'list'
    ? (focus ? 'Entries in ' + monthName(focus) + ' (' + rows.length + '):\n' : 'Latest entries (' + Math.min(rows.length, 80) + ' of ' + rows.length + '):\n') +
      (rows.slice(-80).map(entryLine).join('\n') || 'None.')
    : '';

gezel.output({
  waiting: view.waiting.length,
  uncategorized: view.unsorted.length,
  closeMonth: view.closing,
  stepsLeft: view.view.left.length,
  net: view.netCents / 100,
  summary: listing || (note ? note + ' ' : '') + view.summary,
});

